import{_ as d,a0 as a,w as p,s as w,ao as l,I as e,x as n,a1 as u,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"Qshutdown – 一個先進的關機神器 | LCTT x X-CMD","titleTemplate":false,"description":"Qshutdown – 一個先進的關機神器 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Qshutdown – 一個先進的關機神器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Qshutdown – 一個先進的關機神器 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141119 Qshutdown--An avanced shutdown tool","title":"Qshutdown – 一個先進的關機神器","tag":"201412","desc":""},"relativePath":"201412/20141119 Qshutdown--An avanced shutdown tool.md","filePath":"[post].md"}'),r={name:"201412/20141119 Qshutdown--An avanced shutdown tool.md"};function h(i,t,m,f,g,T){const o=a("Link");return p(),w("div",null,[t[13]||(t[13]=l(`<h1 id="qshutdown-–-一個先進的關機神器" tabindex="-1">Qshutdown – 一個先進的關機神器 <a class="header-anchor" href="#qshutdown-–-一個先進的關機神器" aria-label="Permalink to “Qshutdown – 一個先進的關機神器”">​</a></h1><p>qshutdown是一個QT程序，用於讓計算機在指定時間或者在幾分鐘後關機/重啓/掛起/睡眠。對於那些只在特定時間使用計算機工作的人而言，可能很有用。</p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2014/11/12.png" alt=""></p><p>qshutdown將在最後70秒時顯示3次警告提醒。（如果設置了1分鐘或者“本地時間+1”，它只會顯示一次。）</p><p>該程序使用qdbus來發送關機/重啓/掛起/睡眠請求到gnome或kde會話管理器，或者到HAL或DeviceKit，而如果這些都沒有工作，那麼就會使用‘sudo shutdown -P now’命令進行關機（注意，當發送請求到HAL或DeviceKit，或者使用shutdown命令時，會話不會被保存。如果使用shutdown命令，該程序只會被關機或重啓）。所以，如果在shutdown或reboot時間到時卻什麼都沒發生，這就意味着用户缺少使用shutdown命令的權限。</p><p>在這種情況下，你可以進行以下操作：</p><p>粘貼以下信息到終端：“EDITOR:nano sudo -E visudo”並添加此行：“* ALL = NOPASSWD:/sbin/shutdown”這裏*替換為你的“用户名”或“%組名”。</p><p>倒計時最大計數為1440分鐘（24小時）。配置文件（和日誌文件）位於~/.qshutdown，配置文件為：qshutdown.conf。</p><p>對於管理員：</p><p>在將qshutdonw.conf中的Lock_all選項設置為true後，用户將不能修改設置。如果你使用“sudo chown root -R ~/.qshutdown”和“sudo chmod 744 ~/.qshutdown/qshutdown.conf”命令修改qshutdown.conf的權限後，用户將不能修改配置文件。</p><h3 id="ubuntu中安裝qshutdown" tabindex="-1">Ubuntu中安裝Qshutdown <a class="header-anchor" href="#ubuntu中安裝qshutdown" aria-label="Permalink to “Ubuntu中安裝Qshutdown”">​</a></h3><p>打開終端，然後運行以下命令</p><pre><code>sudo apt-get install qshutdown
</code></pre><h3 id="屏幕截圖" tabindex="-1">屏幕截圖 <a class="header-anchor" href="#屏幕截圖" aria-label="Permalink to “屏幕截圖”">​</a></h3><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2014/11/23.png" alt=""></p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2014/11/31.png" alt=""></p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2014/11/41.png" alt=""></p><hr>`,18)),e("p",null,[t[1]||(t[1]=n("via: ",-1)),u(o,{href:"http://www.ubuntugeek.com/qshutdown-an-avanced-shutdown-tool.html"},{default:s(()=>[...t[0]||(t[0]=[n("http://www.ubuntugeek.com/qshutdown-an-avanced-shutdown-tool.html",-1)])]),_:1})]),e("p",null,[t[5]||(t[5]=n("作者：",-1)),u(o,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:s(()=>[...t[2]||(t[2]=[n("ruchi",-1)])]),_:1}),t[6]||(t[6]=n(" 譯者：",-1)),u(o,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[3]||(t[3]=[n("GOLinux",-1)])]),_:1}),t[7]||(t[7]=n(" 校對：",-1)),u(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=n("本文由 ",-1)),u(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原創翻譯，",-1)),u(o,{href:"http://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[n("Linux中國",-1)])]),_:1}),t[12]||(t[12]=n(" 榮譽推出",-1))])])}const L=d(r,[["render",h]]);export{q as __pageData,L as default};
